-- ═══════════════════════════════════════════════════════════════
-- تسريبات القدرات – الخميس ١٢ نوفمبر ٢٠٢٦
-- 21 سؤالاً: كمي 11 + لفظي 10 (منها 4 في 4 قطع استيعاب)
-- آمن لإعادة التشغيل: guard على وجود أسئلة المجموعة
-- ═══════════════════════════════════════════════════════════════
BEGIN;

INSERT INTO leak_groups (id, title, leak_date, section, question_count, description, is_active, accent_color)
VALUES ('ad121126-2026-4c00-9d00-121120260001', 'تسريبات القدرات – الخميس ١٢ نوفمبر ٢٠٢٦', '2026-11-12', 'mixed', 21, 'أسئلة اختبار القدرات المحوسب ليوم الخميس ١٢ نوفمبر ٢٠٢٦ — القسمان الكمي واللفظي مع الشروح.', true, '#7C3AED')
ON CONFLICT (id) DO NOTHING;

DO $mig$
BEGIN
IF EXISTS (SELECT 1 FROM questions WHERE leak_group_id = 'ad121126-2026-4c00-9d00-121120260001') THEN
  RAISE NOTICE 'أسئلة المجموعة موجودة مسبقاً — تخطي الإدراج';
ELSE
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'دائرة قطرها ٢√٢، رُسم داخلها مربع تقع رؤوسه الأربعة على محيط الدائرة. ما محيط المربع؟', '["٢", "٤", "٨", "١٦"]'::jsonb, 2, 'قطر الدائرة يساوي قطر المربع، أي طول القطر الواصل بين رأسين متقابلين. في المربع، طول الضلع = طول القطر ÷ √٢، ولذلك طول الضلع = ٢√٢ ÷ √٢ = ٢. محيط المربع = ٤ × ٢ = ٨.', NULL, 'ad121126-2026-4c00-9d00-121120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'دائرتان نصف قطر الأولى ٣ سم ونصف قطر الثانية ٦ سم. ما نسبة مساحة الدائرة الصغرى إلى مساحة الدائرة الكبرى؟', '["١/٢", "٢/٣", "١/٤", "٤/٦"]'::jsonb, 2, 'مساحة الدائرة تساوي π × مربع نصف القطر. لذلك نسبة المساحتين = ٣² ÷ ٦² = ٩ ÷ ٣٦. نبسّط الكسر بالقسمة على ٩ فنحصل على ١/٤.', NULL, 'ad121126-2026-4c00-9d00-121120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'في الشكل مستطيل مكوَّن من مربعين متطابقين، ورُسم قطر في كل مربع. قارن بين القيمة الأولى، وهي قياس الزاوية س، والقيمة الثانية، وهي قياس الزاوية ص.', '["القيمة الأولى أكبر", "القيمة الثانية أكبر", "القيمتان متساويتان", "المعطيات غير كافية"]'::jsonb, 2, 'قطر المربع يقسم الزاوية القائمة إلى زاويتين متساويتين. قياس كل زاوية = ٩٠ ÷ ٢ = ٤٥ درجة. لذلك قياس س = ٤٥ درجة وقياس ص = ٤٥ درجة، فتتساوى القيمتان.', 'https://czzcmbxejxbotjemyuqf.supabase.co/storage/v1/object/public/question-figures/qudurat_nov12_q008_twosquares.png', 'ad121126-2026-4c00-9d00-121120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الحساب', 'اختيار من متعدد', 'سيارتان تنطلقان من النقطة نفسها في اتجاهين متعاكسين. سرعة السيارة الأولى س كم/ساعة، وسرعة الثانية ص كم/ساعة. ما التعبير الذي يمثل المسافة بين السيارتين بعد ساعة واحدة؟', '["س × ص", "ص ÷ س", "ص − س", "س + ص"]'::jsonb, 3, 'عندما تتحرك سيارتان في اتجاهين متعاكسين، فإن المسافة بينهما تزداد بمجموع المسافتين المقطوعتين. المسافة = السرعة × الزمن، وبعد ساعة تقطع الأولى س كم والثانية ص كم. لذلك المسافة بينهما = س + ص.', NULL, 'ad121126-2026-4c00-9d00-121120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الجبر', 'اختيار من متعدد', 'إذا كان العدد (س + ٤) يقبل القسمة على ٧ دون باقٍ، فعلى أي عدد يقبل المقدار (٢س + ١) القسمة دون باقٍ؟', '["٢", "٤", "٥", "٧"]'::jsonb, 3, 'نعلم أن س + ٤ من مضاعفات العدد ٧. نعيد كتابة المقدار المطلوب: ٢س + ١ = ٢(س + ٤) − ٧. وبما أن كلا الحدين يقبل القسمة على ٧، فإن الفرق بينهما يقبل القسمة على ٧ أيضًا.', NULL, 'ad121126-2026-4c00-9d00-121120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الجبر', 'اختيار من متعدد', 'إذا كانت النقطة (٩، ٥) منتصف القطعة المستقيمة الواصلة بين النقطتين (س، ٤) و(٤، ص)، فقارن بين القيمة الأولى س والقيمة الثانية ص.', '["القيمة الأولى أكبر", "القيمة الثانية أكبر", "القيمتان متساويتان", "المعطيات غير كافية"]'::jsonb, 0, 'إحداثيا نقطة المنتصف يساويان متوسط إحداثيي طرفي القطعة المستقيمة. نحسب س من المعادلة (س + ٤) ÷ ٢ = ٩، فنحصل على س = ١٤. ونحسب ص من (٤ + ص) ÷ ٢ = ٥، فنحصل على ص = ٦، ولذلك س أكبر من ص.', NULL, 'ad121126-2026-4c00-9d00-121120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'يتقاطع مستقيمان، وقياس إحدى الزاويتين ٢(س + ٤) درجة، وقياس الزاوية المقابلة لها بالرأس (٦س − ٤) درجة. إذا كانت الزاوية ص مجاورة لهما، فأوجد قياس ص.', '["١٢٠", "١٥٠", "١٥٦", "١٦٦"]'::jsonb, 3, 'الزاويتان المتقابلتان بالرأس متساويتان، لذلك ٢(س + ٤) = ٦س − ٤. بحل المعادلة نجد ٢س + ٨ = ٦س − ٤، ومنه س = ٣، فتكون الزاوية = ١٤ درجة. الزاوية ص مكملة لها، إذن ص = ١٨٠ − ١٤ = ١٦٦ درجة.', NULL, 'ad121126-2026-4c00-9d00-121120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'عامل يحفر حفرة مكعبة حجمها ١ م³ في دقيقة واحدة. كم دقيقة يحتاج لحفر حفرة أبعادها ٢ م × ٢ م × ٢ م بالمعدل نفسه؟', '["٢", "٤", "٦", "٨"]'::jsonb, 3, 'حجم المكعب يساوي الطول × العرض × الارتفاع. حجم الحفرة المطلوبة = ٢ × ٢ × ٢ = ٨ م³. وبما أن العامل يحفر ١ م³ كل دقيقة، فإنه يحتاج إلى ٨ ÷ ١ = ٨ دقائق.', NULL, 'ad121126-2026-4c00-9d00-121120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الجبر', 'اختيار من متعدد', 'لدى سلمى أختان؛ الأولى أكبر منها بـ٨ سنوات، والثانية أصغر منها بسنتين. إذا كان حاصل ضرب عمري الأختين ٥٦، فما عمر سلمى؟', '["٦", "٨", "١٠", "١٢"]'::jsonb, 0, 'نفترض أن عمر سلمى س، فيكون عمر أختها الكبرى س + ٨، والصغرى س − ٢. نكتب المعادلة (س + ٨) × (س − ٢) = ٥٦. بتجربة س = ٦ نجد أن ١٤ × ٤ = ٥٦، ولذلك عمر سلمى ٦ سنوات.', NULL, 'ad121126-2026-4c00-9d00-121120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الجبر', 'اختيار من متعدد', 'إذا كان (س × ١/٨) ÷ ٧ = ٢٤/٧، فأوجد قيمة س.', '["٣", "٤", "٩٦", "١٩٢"]'::jsonb, 3, 'نضرب طرفي المعادلة في ٧ لإزالة المقام المشترك. نحصل على س × ١/٨ = ٢٤، أي س ÷ ٨ = ٢٤. نضرب الطرفين في ٨، فنجد س = ٢٤ × ٨ = ١٩٢.', NULL, 'ad121126-2026-4c00-9d00-121120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الإحصاء والاحتمالات', 'اختيار من متعدد', 'شركة لديها ٤٢٠ موظفًا، ويمثل الموظفون السعوديون قطاعًا زاويته ١٢٠° في مخطط دائري. كم موظفًا سعوديًا يجب إضافته حتى يصبح السعوديون نصف إجمالي موظفي الشركة بعد الإضافة، مع بقاء عدد الموظفين الآخرين ثابتًا؟', '["٤٠", "٧٠", "١٠٠", "١٤٠"]'::jsonb, 3, 'نحسب عدد السعوديين الحاليين: ٤٢٠ × ١٢٠ ÷ ٣٦٠ = ١٤٠ موظفًا، فيكون عدد غير السعوديين ٤٢٠ − ١٤٠ = ٢٨٠. لكي يصبح السعوديون نصف الإجمالي، يجب أن يتساوى عددهم مع عدد غير السعوديين. لذلك نضيف ٢٨٠ − ١٤٠ = ١٤٠ موظفًا سعوديًا.', NULL, 'ad121126-2026-4c00-9d00-121120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'التناظر اللفظي', 'اختيار من متعدد', 'ركوب : ترجل', '["مغادرة : رحيل", "إقامة : ظعن", "صلاة : قصر", "سفر : غربة"]'::jsonb, 1, 'الركوب يعني الصعود إلى وسيلة النقل، والترجل يعني النزول منها، فبينهما تقابل في المعنى. كذلك الإقامة تعني الاستقرار في مكان، والظعن يعني الارتحال عنه. أما المغادرة والرحيل فمتقاربان في المعنى، وليسا متقابلين.', NULL, 'ad121126-2026-4c00-9d00-121120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'التناظر اللفظي', 'اختيار من متعدد', 'ناقة : حوار', '["فرس : مهر", "ذئب : سرحان", "اصطبل : خيل", "ضرغام : أسد"]'::jsonb, 0, 'الحوار هو صغير الناقة، فالعلاقة بين الحيوان وصغيره. والمهر هو صغير الفرس، لذلك تتطابق العلاقة في هذا الزوج. أما السرحان والضرغام فمن أسماء الحيوانات نفسها، والاصطبل مكان لإيواء الخيل.', NULL, 'ad121126-2026-4c00-9d00-121120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'التناظر اللفظي', 'اختيار من متعدد', 'حليب : لبن', '["جبنة : زبدة", "وبر : صوف", "دقيق : خبز", "عصير : ماء"]'::jsonb, 2, 'يمكن تحويل الحليب إلى لبن بعملية التخمر، فالعلاقة بين مادة أولية ومنتج يُصنع منها. وبالمثل يُستخدم الدقيق في صناعة الخبز. أما الجبنة والزبدة فمنتجان مختلفان، ولا يمثل أحدهما مادة أولية للآخر.', NULL, 'ad121126-2026-4c00-9d00-121120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'الخطأ السياقي', 'اختيار من متعدد', 'لا تدخر ما تبقى بعد الاقتصاد، بل أنفق ما تبقى بعد الادخار. حدد الكلمة غير المناسبة للسياق.', '["تدخر", "الاقتصاد", "أنفق", "الادخار"]'::jsonb, 1, 'توضح العبارة أن الادخار ينبغي أن يكون جزءًا أساسيًا من تنظيم المال، لا مجرد مبلغ متبقٍ. لذلك تكون الصياغة المناسبة: لا تدخر ما تبقى بعد الإنفاق، بل أنفق ما تبقى بعد الادخار. كلمة الاقتصاد في الموضع الأول لا تحقق المقابلة المقصودة بين الإنفاق والادخار.', NULL, 'ad121126-2026-4c00-9d00-121120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'المفردة الشاذة', 'اختيار من متعدد', 'اختر المفردة الشاذة من الكلمات الآتية.', '["فقر", "غنى", "جوع", "عطش"]'::jsonb, 1, 'الفقر والجوع والعطش حالات تدل على النقص أو الحاجة إلى شيء أساسي. أما الغنى فيدل على الوفرة وامتلاك المال أو الموارد. لذلك يختلف الغنى عن الكلمات الثلاث الأخرى في المعنى العام.', NULL, 'ad121126-2026-4c00-9d00-121120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'المفردة الشاذة', 'اختيار من متعدد', 'اختر المفردة الشاذة من الكلمات الآتية.', '["هدية", "نفقة", "هبة", "عطية"]'::jsonb, 1, 'الهدية والهبة والعطية كلمات تدل على تقديم شيء لشخص آخر على سبيل التبرع أو الإحسان. أما النفقة فهي مال يُصرف لتغطية الاحتياجات أو الالتزامات المعيشية. لذلك تختلف النفقة عن بقية الكلمات.', NULL, 'ad121126-2026-4c00-9d00-121120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'وفقًا للقطعة، ما نسبة الموارد المائية التي توفرها السدود الطبيعية؟', '["٠٫٥٪", "١٪", "٢٪", "٢٫٥٪"]'::jsonb, 0, 'نسبة الموارد المائية كلها تساوي ١٠٠٪. تجمع النسبتان المذكورتان للبحار والمياه الجوفية إلى ٨٦٪ + ١٣٫٥٪ = ٩٩٫٥٪. النسبة المتبقية للسدود = ١٠٠٪ − ٩٩٫٥٪ = ٠٫٥٪.', NULL, 'ad121126-2026-4c00-9d00-121120260001', 'e1b12001-2026-4c00-9d00-000000000001', 'السدود
يجب على البلدان أن تكون لها موارد مائية وفيرة، وأن توفر موارد غذائية ومائية. ويمكن أن توفر موارد مائية من خلال البحار بنسبة ٨٦٪، والمياه الجوفية بنسبة ١٣٫٥٪، والنسبة الباقية للسدود الطبيعية.', 1, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'ما علاقة عبارة «ولكنها كذلك تعني التفسير الشفهي لأفكار الكاتب» بما قبلها؟', '["تعليل", "استنتاج", "تفسير", "استدراك"]'::jsonb, 3, 'توضح الجملة الأولى أن القراءة الجهرية تشمل تمييز الكلمات وفهم معانيها. ثم جاءت العبارة التالية لتضيف جانبًا آخر من مفهوم القراءة الجهرية، وهو التعبير الشفهي عن أفكار الكاتب. واستخدام لكن يدل هنا على الاستدراك وإضافة معنى لم تتضمنه العبارة السابقة.', NULL, 'ad121126-2026-4c00-9d00-121120260001', 'e1b12002-2026-4c00-9d00-000000000002', 'القراءة الجهرية
القراءة الجهرية تعني تمييز الكلمات والإلمام بمعناها، ولكنها كذلك تعني التفسير الشفهي لأفكار الكاتب لأفراد آخرين؛ إذ إن الناس يقرؤون لتسلية الآخرين، وإيصال المعلومة إليهم، وإقناعهم بفكرة ما.', 1, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'ما العلاقة بين قلة وعي الناس بالبرامج الأمنية وزيادة معدلات الاختراق التقني؟', '["تعليلية (سببية)", "توافقية", "ترادفية", "تضادية"]'::jsonb, 0, 'توضح القطعة أن ضعف المعرفة بالبرامج الأمنية من العوامل التي تساعد على زيادة الاختراقات. فقلة الوعي تمثل سببًا، وارتفاع معدلات الاختراق يمثل نتيجة مترتبة عليه. لذلك العلاقة بين العبارتين سببية وليست ترادفًا أو تضادًا.', NULL, 'ad121126-2026-4c00-9d00-121120260001', 'e1b12003-2026-4c00-9d00-000000000003', 'الاختراق التقني
مع انتشار الأجهزة وقلة وعي الناس بالبرامج الأمنية، زادت معدلات الاختراق في العالم.', 1, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'وفقًا للقطعة، أي الأمراض الآتية قد يكون تأثيرها على صحة الإنسان أشد خطورة؟', '["السكري والبدانة وارتفاع ضغط الدم", "السل والملاريا والإيدز", "السل والملاريا", "الإنفلونزا والملاريا"]'::jsonb, 0, 'تذكر القطعة أن الأمراض المزمنة قد تكون أكثر تأثيرًا في صحة الإنسان من بعض الأمراض المعدية. وقد حددت السكري والسمنة وارتفاع ضغط الدم أمثلة لهذه الأمراض المزمنة. كما أشارت إلى أن البدانة والسكري قد يزيدان الوفيات المرتبطة ببعض الأمراض الأخرى.', NULL, 'ad121126-2026-4c00-9d00-121120260001', 'e1b12004-2026-4c00-9d00-000000000004', 'أمراض مزمنة
هناك أمراض مزمنة مثل السكري والسمنة وارتفاع ضغط الدم، وقد يكون تأثيرها على صحة الإنسان أقوى وأكثر خطورة من بعض الأمراض مثل السل والملاريا والإيدز.
وقد تزيد البدانة والسكري من معدل وفيات مرض الإيدز والملاريا.', 1, 'active', false);
