DECLARE n INT; nq INT; nv INT;
BEGIN
  SELECT COUNT(*) INTO n FROM questions WHERE leak_group_id = 'ad121126-2026-4c00-9d00-121120260001';
  SELECT COUNT(*) INTO nq FROM questions WHERE leak_group_id = 'ad121126-2026-4c00-9d00-121120260001' AND section = 'quant';
  SELECT COUNT(*) INTO nv FROM questions WHERE leak_group_id = 'ad121126-2026-4c00-9d00-121120260001' AND section = 'verbal';
